-- Access QueryDef: ra_impNewSumCompRslt
-- Type: 0

SELECT i.ipgChKey, i.ipgcYyyy, i.cstAgPnCode, i.excelPres, i.excelAccp, i.sqlPres, i.sqlAccp, i.diffPres, i.diffAccp, i.cstapKey, pa.ipgpSmTtl AS agSumTtl, pi.ipgpSmTtl AS inSumTtl, po.ipgpSmTtl AS otSumTtl, rpt.rcPresTtl, rat.rcAccpTtl, np.np_presentedAccum, np.np_acceptedAccum, IIf(IsNull([agSumTtl]),IIf(IIf(IsNull([diffPres]),0,[diffPres])=IIf(IsNull([np_presentedAccum]),0,[np_presentedAccum]),"принят неплан","непонятно"),IIf(IIf(IsNull([diffPres]),0,[diffPres])=IIf(IsNull([rcPresTtl]),0,[rcPresTtl]),"изменения с минусом","непонятно")) AS reasonPres, IIf(IsNull([agSumTtl]),IIf(IIf(IsNull([diffAccp]),0,[diffAccp])=IIf(IsNull([np_acceptedAccum]),0,[np_acceptedAccum]),"принят неплан","непонятно"),IIf(IIf(IsNull([diffAccp]),0,[diffAccp])=IIf(IsNull([rcAccpTtl]),0,[rcAccpTtl]),"изменения с минусом","непонятно")) AS reasonAccp, IIf([reasonPres]<>"непонятно" And [reasonAccp]<>"непонятно","определена","не определена") AS reason
FROM (((((ra_impNewSumCompare AS i LEFT JOIN (SELECT * FROM ags_ipgPn AS p WHERE p.ipgpSh = 2)  AS pa ON (i.cstapKey = pa.ipgpCstAgPn) AND (i.ipgcIpgLate = pa.ipgpIpg)) LEFT JOIN (SELECT * FROM ags_ipgPn AS p WHERE p.ipgpSh = 1)  AS pi ON (i.ipgcIpgLate = pi.ipgpIpg) AND (i.cstapKey = pi.ipgpCstAgPn)) LEFT JOIN (SELECT * FROM ags_ipgPn AS p WHERE p.ipgpSh = 3)  AS po ON (i.cstapKey = po.ipgpCstAgPn) AND (i.ipgcIpgLate = po.ipgpIpg)) LEFT JOIN (SELECT z.rcYyyy, z.ra_cac, Sum(z.raсs_total) AS rcPresTtl FROM (SELECT s.raсs_total, Year([rac_datePeriod]) AS rcYyyy, r.ra_cac, Year([ra_datePeriod]) AS raYyyy, IIf(Year([c]![rac_datePeriod])=Year([r].[ra_datePeriod]),True,False) AS yCompare FROM (ags_ra_chSmLt AS s INNER JOIN ags_ra_change AS c ON s.raсs_raс = c.rac_key) INNER JOIN ags_ra AS r ON c.raс_ra = r.ra_key WHERE (((s.raсs_total)<0) And ((IIf(Year(c!rac_datePeriod)=Year(r.ra_datePeriod),True,False))=False)))  AS z GROUP BY z.rcYyyy, z.ra_cac)  AS rpt ON (i.cstapKey = rpt.ra_cac) AND (i.ipgcYyyy = rpt.rcYyyy)) LEFT JOIN (SELECT z.rcYyyy, z.ra_cac, Sum(z.raсs_total) AS rcAccpTtl FROM (SELECT s.raсs_total, Year([rac_datePeriod]) AS rcYyyy, r.ra_cac, Year([ra_datePeriod]) AS raYyyy, IIf(Year([c]![rac_datePeriod])=Year([r].[ra_datePeriod]),True,False) AS yCompare, c.ra_sent FROM (ags_ra_chSmLt AS s INNER JOIN ags_ra_change AS c ON s.raсs_raс = c.rac_key) INNER JOIN ags_ra AS r ON c.raс_ra = r.ra_key WHERE (((s.raсs_total)<0) And ((IIf(Year(c!rac_datePeriod)=Year(r.ra_datePeriod),True,False))=False) And ((c.ra_sent) Is Not Null)))  AS z GROUP BY z.rcYyyy, z.ra_cac)  AS rat ON (i.cstapKey = rat.ra_cac) AND (i.ipgcYyyy = rat.rcYyyy)) LEFT JOIN (SELECT i.cstAgPnCode, i.np_presentedAccum, i.np_acceptedAccum FROM ipgChRsltPlCstSum AS i WHERE (((i.cstAgPnCode) Is Not Null) AND ((i.np_presentedAccum)<>0) AND ((Month([dateRslt]))=12)))  AS np ON i.cstAgPnCode = np.cstAgPnCode;
